---level39 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl39_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		game.pauseLogic();		sound.play("50-1")		if dialog.show("Level39-1", faceJingya) ==1 then break end		if dialog.show("Level39-2", faceManyi) ==1 then break end		if dialog.show("Level39-3", faceDeyi) ==1 then break end		--set story viewed flag        global.setBool("lvl39_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		game.resumeLogic();		isSkip = false	until trueendif isSkip then	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end